// This function is to be wrapped around every interaction callback. It is not
// used here, to ensure that any composite actions which pass through invalid
// intermediate steps blah blah
export function act<T>(func: () => T): T {
  return docAtom.batch('render', () => network.sample(() =>
    func()
  ))
}


