export function addNodeToGraph(graphC: Cursor<Model.Graph>, name?: string): Model.NodeId {
  const nodeId = newId('node')
  const node: Model.Node = {
    id: nodeId,
    name: name || ""
  }
  graphC.select('nodes').update((nodes) => ({...nodes, [nodeId]: node}))
  return nodeId
}

