export function insertStepIntoSteps<T extends Model.Step>(step: T, stepsC: Cursor<Model.Steps>, index: number) {
  stepsC.update((steps) => arrInsert(steps, index, step))
  return stepsC.select(index) as any as Cursor<T>  // we know what it is; we just inserted it
}

export function addReferenceNodeToGraph(nodeId: string, graphC: Cursor<Model.Graph>, blockC: Cursor<Model.Block>): Model.NodeId {
  const info = nodeInfo(blockC, nodeId)
  if (!info.name) {
    NodeInfo.nodeC(info)._('name').set('nameless node')
  }
  return addCodeCallFromRaw(nodeId, graphC, true).nodeId
}

export function insertNewGraphIntoStepsWithReference(nodeId: Model.NodeId, stepsC: Cursor<Model.Steps>, index: number, blockC: Cursor<Model.Block>) {
  const newGraphC = insertStepIntoSteps(makeNewGraph(), stepsC, index)
  const newNodeId = addReferenceNodeToGraph(nodeId, newGraphC, blockC)
  return {graphC: newGraphC, nodeId: newNodeId}
}

export function deleteStepFromSteps(stepC: Cursor<Model.Step>) {
  const stepsC = parentSteps(stepC)
  stepsC.update((steps) => _.without(steps, stepC.get()))
}

// OK if you right-click a node (X) and say "make a code call from that!" then what happens?
// * If X is in a graph, and X doesn't have a call coming from it, you just tack your call onto the end of that puppy
// * If not, you're going to have to make a new graph, put a reference to X in there, and then make a code call from the reference
//     (if the node is in a step (graph or switch output) we make the graph right after that step;
//      if not (function input) we make the graph at the end of the body?)
export function prepareNodeForNewCall(blockC: Cursor<Model.Block>, nodeId: Model.NodeId) {
  const info = nodeInfo(blockC, nodeId)
  if (info.type === 'graph' && !info.usingCallId) {
    return {nodeId, graphC: NodeInfo.graphC(info)}
  } else {
    let stepsC: Cursor<Model.Steps>
    let index: number
    switch (info.type) {
    case 'input': {
      stepsC = blockC._('steps')
      index = stepsC.get().length
      break }
    case 'graph': {
      const stepC = NodeInfo.graphC(info)
      stepsC = parentSteps(stepC)
      index = stepsC.get().indexOf(stepC.get()) + 1
      break }
    case 'switch-output': {
      const stepC = NodeInfo.switchC(info)
      stepsC = parentSteps(stepC)
      index = stepsC.get().indexOf(stepC.get()) + 1
      break }
    }
    const {nodeId: newRefNodeId, graphC: newGraphC} =
      insertNewGraphIntoStepsWithReference(referredOrOwnNodeId(blockC, nodeId), stepsC!, index!, blockC)
    // console.log("inserted new graph!", newRefNodeId, newGraphC)
    return {nodeId: newRefNodeId, graphC: newGraphC}
  }
}

export function addCodeCallFrom(blockC: Cursor<Model.Block>, nodeId: Model.NodeId, codeMaker = (inputNodeId: string) => inputNodeId) {
  const {nodeId: newNodeId, graphC} = prepareNodeForNewCall(blockC, nodeId)
  return addCodeCallFromRaw(newNodeId, graphC, false, codeMaker)
}

// This function adds a code call from a node, into a given graph. The node
// given does not have to be in the graph, but if it is indeed not the graph,
// the call better be collapsed! (so you're creating a reference.)
export function addCodeCallFromRaw(inputNodeId: Model.NodeId, graphC: Cursor<Model.Graph>, collapsed: boolean = false, codeMaker = (inputNodeId: string) => inputNodeId) {
  const newOutputNodeId = addNodeToGraph(graphC)
  const newCallId = newId('call')
  const newCall: Model.CodeCall = {
    id: newCallId,
    callType: 'code',
    inputs: [
      {
        outside: inputNodeId,
        inside: inputNodeId
      }
    ],
    code: codeMaker(inputNodeId),
    outputs: [
      {
        outside: newOutputNodeId
      }
    ],
    collapsed: collapsed
  }
  graphC.select('calls').update((calls) => ({...calls, [newCallId]: newCall}))
  return { callId: newCallId, nodeId: newOutputNodeId }
}

export function addDefinitionCallFrom(blockC: Cursor<Model.Block>, nodeId: Model.NodeId, definitionId: Model.DefinitionId) {
  const {nodeId: newNodeId, graphC} = prepareNodeForNewCall(blockC, nodeId)
  addDefinitionCallFromRaw(newNodeId, graphC, definitionId)
}

// This function adds a code call from a node, into a given graph. The node
// given does not have to be in the graph, but if it is indeed not the graph,
// the call better be collapsed! (so you're creating a reference.)
export function addDefinitionCallFromRaw(inputNodeId: Model.NodeId, graphC: Cursor<Model.Graph>, definitionId: Model.DefinitionId) {
  const newCall: Model.DefinitionCall = {
    id: newId('call'),
    callType: 'definition',
    inputs:
      definitionById(definitionId).get().inputs.map(({id}, i) => ({
        outside: i === 0 ? inputNodeId : addEmptyCodeCall(graphC),
        inside: id
      })),
    definition: definitionId,
    outputs: [
      {
        outside: addNodeToGraph(graphC)
      }
    ]
  }
  graphC.select('calls').update((calls) => ({...calls, [newCall.id]: newCall}))
  return newCall.outputs[0].outside
}

export function addDefinitionCallWithDefaults(graphC: Cursor<Model.Graph>, definitionId: Model.DefinitionId) {
  const newCall: Model.DefinitionCall = {
    id: newId('call'),
    callType: 'definition',
    inputs:
      definitionById(definitionId).get().inputs.map((input, i) => ({
        outside: addEmptyCodeCall(graphC, undefined, input.settings[input.activeSetting]),
        inside: input.id
      })),
    definition: definitionId,
    outputs: [
      {
        outside: addNodeToGraph(graphC)
      }
    ]
  }
  graphC.select('calls').update((calls) => ({...calls, [newCall.id]: newCall}))
  return newCall.outputs[0].outside
}

export function addListOpCallFrom(blockC: Cursor<Model.Block>, nodeId: Model.NodeId, listOpType: Model.ListOpType) {
  const {nodeId: newNodeId, graphC} = prepareNodeForNewCall(blockC, nodeId)
  addListOpCallFromRaw(newNodeId, graphC, listOpType)
}

export function addListOpCallFromRaw(inputNodeId: Model.NodeId, graphC: Cursor<Model.Graph>, listOpType: Model.ListOpType) {
  const newOutputNodeId = addNodeToGraph(graphC)
  const newCallId = newId('call')
  const elementNodeId = newId('node')
  const indexNodeId = newId('node')
  const identityGraphId = newId('graph')
  const identityNodeId = newId('node')
  const identityCallId = newId('call')
  const newCall: Model.ListOpCall = {
    id: newCallId,
    callType: 'list-op',
    inputs: [
      {
        outside: inputNodeId,
        inside: inputNodeId
      }
    ],
    listOpType,
    block: {
      id: newId('block'),
      inputs: [
        { id: elementNodeId, name: 'item' },
        { id: indexNodeId,   name: 'index' },
      ],
      steps: [{
        stepType: 'graph',
        id: identityGraphId,
        nodes: {
          [identityNodeId]: {
            id: identityNodeId,
            name: ""
          }
        },
        calls: {
          [identityCallId]: {
            id: identityCallId,
            callType: 'code',
            inputs: [{
              outside: elementNodeId,
              inside: elementNodeId,
            }],
            code: elementNodeId,
            outputs: [{
              outside: identityNodeId
            }],
            collapsed: true
          }
        }
      }]
    },
    elementNodeId,
    indexNodeId,
    outputs: [
      {
        outside: newOutputNodeId
      }
    ]
  }
  graphC.select('calls').update((calls) => ({...calls, [newCallId]: newCall}))
  return newOutputNodeId
}

export function addCombiningCodeCallRaw(
    nodeId1: Model.NodeId, nodeId2: Model.NodeId,
    graphC: Cursor<Model.Graph>, blockC: Cursor<Model.Block>) {
  const newCallId = addCodeCallFromRaw(nodeId1, graphC).callId
  const newCallC = graphC._('calls')._(newCallId) as Cursor<Model.CodeCall>
  // console.log("newCallC", newCallId newCallC, newCallC.get())
  addInput(newCallC, nodeId2, 1)
  newCallC._('code').set(`[${nodeId1}, ${nodeId2}]`)
}

export function addEmptyCodeCall(graphC: Cursor<Model.Graph>, name?: string, code?: string) {
  const newOutputNodeId = addNodeToGraph(graphC, name)
  const newCallId = newId('call')
  const newCall: Model.CodeCall = {
    id: newCallId,
    callType: 'code',
    inputs: [
    ],
    code: code || "",
    outputs: [
      {
        outside: newOutputNodeId
      }
    ],
    collapsed: true
  }
  graphC.select('calls').update((calls) => ({...calls, [newCallId]: newCall}))
  return newOutputNodeId
}
