export function deleteInputFromCall(inputNodeId: Model.NodeId, callId: Model.CallId, graphC: Cursor<Model.Graph>, blockC: Cursor<Model.Block>) {
  console.log("deleteInputFromCall", arguments)
  deleteSubtree(blockC, inputNodeId)
  graphC._('calls')._(callId)._('inputs').update((inputs) =>
    _.filter(inputs, (input) => input.outside !== inputNodeId))
}

export function replaceInput(callC: Cursor<Model.Call>, oldNodeId: Model.NodeId, newNodeId: Model.NodeId) {
  const inputIndex = _.findIndex(callC.get().inputs, {outside: oldNodeId})
  callC._('inputs')._(inputIndex)._('outside').set(newNodeId)
}

export function addInput(callC: Cursor<Model.Call>, nodeId: Model.NodeId, index?: number) {
  callC._('inputs').update((inputs) => arrInsert(inputs, index || callC.get().inputs.length, {
    outside: nodeId, inside: nodeId
  }))
}

export function moveSubtree(
    blockC: Cursor<Model.Block>,
    nodeId: Model.NodeId,
    newGraphC: Cursor<Model.Graph>
    ) {
  console.log("movesubtree")
  const oldGraphC = NodeInfo.graphC(nodeInfo(blockC, nodeId) as GraphNodeInfo)
  console.log('oldGraphC', oldGraphC, nodeInfo(blockC, nodeId))
  moveSubtreeIntoGraphLeavingHoleIfNeeded(blockC, nodeId, oldGraphC, newGraphC)
  deleteGraphIfEmpty(oldGraphC)
}

export function moveSubtreeIntoGraphLeavingHoleIfNeeded(
    blockC: Cursor<Model.Block>,
    nodeId: Model.NodeId,
    oldGraphC: Cursor<Model.Graph>,
    newGraphC: Cursor<Model.Graph>) {
  // Replace the node with an empty node, if needed
  const usingCallId = (nodeInfo(blockC, nodeId) as GraphNodeInfo).usingCallId
  if (usingCallId) {
    const emptyNodeId = addEmptyCodeCall(oldGraphC)
    replaceInput(oldGraphC.select('calls').select(usingCallId), nodeId, emptyNodeId)
  }

  // And do the move!
  moveSubtreeIntoGraph(blockC, oldGraphC, newGraphC, nodeId)
}

