export function collapseCall(callC: Cursor<Model.CodeCall>, graphC: Cursor<Model.Graph>, blockC: Cursor<Model.Block>) {
  // We assume all inputs are references! Check this yourself!
  CursorV.elems(callC._('inputs').fetch()).forEach((inputC) => {
    const oldInputNodeId = inputC.value().outside
    const referredNodeId = (nodeInfo(blockC, oldInputNodeId) as GraphNodeInfo).referredNodeId!
    deleteSubtree(blockC, oldInputNodeId)
    inputC._('outside').set(referredNodeId)
  })
  callC._('collapsed').set(true)
}

export function expandCall(callC: Cursor<Model.CodeCall>, graphC: Cursor<Model.Graph>, blockC: Cursor<Model.Block>) {
  CursorV.elems(callC._('inputs').fetch()).forEach((inputC) => {
    const oldInputNodeId = inputC.value().outside
    const newReference = addReferenceNodeToGraph(oldInputNodeId, graphC, blockC)
    inputC._('outside').set(newReference)
  })
  callC._('collapsed').set(false)
}

export function moveSubtreeIntoGraph(blockC: Cursor<Model.Block>, oldGraphC: Cursor<Model.Graph>, newGraphC: Cursor<Model.Graph>, nodeId: Model.NodeId) {
  // If it has a defining call...
  const definingCallId = (nodeInfo(blockC, nodeId) as GraphNodeInfo).definingCallId
  if (definingCallId) {
    const definingCallC = oldGraphC._('calls')._(definingCallId)
    
    // ...move the call's inputs
    definingCallC.get().inputs.forEach(({outside}) => {
      if (oldGraphC.get().nodes[outside]) {
        moveSubtreeIntoGraph(blockC, oldGraphC, newGraphC, outside)
      }
    })

    // ...and the call itself
    newGraphC._('calls').update((calls) => ({...calls, [definingCallId]: definingCallC.get()}))
    definingCallC.delete()
  }

  // Move the node itself
  console.log('graphC is', oldGraphC)
  const oldNodeC = oldGraphC._('nodes')._(nodeId)
  newGraphC._('nodes').update((nodes) => ({...nodes, [nodeId]: oldNodeC.get()}))
  oldNodeC.delete()
}

export function deleteGraphIfEmpty(graphC: Cursor<Model.Graph>) {
  console.log('deleteGraphIfEmpty', graphC.get().id, graphC.get().nodes)
  if (_.isEmpty(graphC.get().nodes)) {
    console.log("it's empty!")
    deleteStepFromSteps(graphC)
  }
}

export function deleteSubtree(blockC: Cursor<Model.Block>, nodeId: Model.NodeId) {
  console.log('deleteSubtree', nodeId)
  const info = nodeInfo(blockC, nodeId) as GraphNodeInfo
  const graphC = NodeInfo.graphC(info)

  // Delete the node itself
  graphC.select('nodes').update((nodes) => _.omit(nodes, [nodeId]))

  // If it has a defining call...
  const definingCallId = info.definingCallId
  if (definingCallId) {
    const definingCall = graphC.get().calls[definingCallId]
    // and it's not collapsed...
    if (!(definingCall.callType === 'code' && definingCall.collapsed)) {
      // ...delete the call's inputs
      graphC.get().calls[definingCallId].inputs.forEach(({outside}) =>
        deleteSubtree(blockC, outside)
      )
    }

    // ...and the call itself
    graphC.select('calls').update((calls) => _.omit(calls, [definingCallId]))
  }

  // // If it is used in a call...
  // const usingCall = callUsingNode(node, graph)
  // if (usingCall && usingCall.type === 'call-definition') {
  //
  // }
}

export function ensureCallHasInputForNode(blockC: Cursor<Model.Block>, callC: Cursor<Model.CodeCall>, nodeId: Model.NodeId) {
  if (callC._('collapsed').get()) {
    const existingInputForCell = _.find(callC.get().inputs, ({outside}) => {
      return outside === nodeId
    })
    if (existingInputForCell) {
      return existingInputForCell.inside
    } else {
      addInput(callC, nodeId)
      return nodeId
    }
  } else {
    const existingInputForCell = _.find(callC.get().inputs, ({outside}) => {
      return (nodeInfo(blockC, outside) as GraphNodeInfo).referredNodeId === nodeId
    })
    if (existingInputForCell) {
      return existingInputForCell.inside
    } else {
      const referenceNodeId = addReferenceNodeToGraph(nodeId, callC.parent().parent(), blockC)
      addInput(callC, referenceNodeId)
      return referenceNodeId
    }
  }
}

// TODO: this hackishly uses the fact that IDs are not actually global, but just per-definition
// E.g., blocks in list operations won't actually have unique IDs! nooooooo
export function duplicateDefinition(definitionC: Cursor<Model.Definition>) {
  const definition = definitionC.get()
  const newDefinition = {...definition, id: newId('definition'), name: 'copy of ' + definition.name}
  documentC.select('definitions').update((definitions) =>
    arrInsert(definitions, definitions.indexOf(definition) + 1, newDefinition)
  )
}

export function deleteDefinition(definitionC: Cursor<Model.Definition>) {
  documentC.select('definitions').update((definitions) => _.without(definitions, definitionC.get()))
}

